sys_script_include.script:
var EnrollmentValidation = Class.create();
EnrollmentValidation.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	validateEnrollment: function() {
		var user = gs.getUserID();
		var scheduleId = this.getParameter('sysparm_schedule');

		//obtendo agenda e informações do curso
		var scheduleGR = new GlideRecord('x_1131775_traini_0_schedules');

		if (!scheduleGR.get(scheduleId)){
			return 'schedule_not_found';
		}

		var courseID = scheduleGR.course.toString();
		var trainingDate = scheduleGR.training_date;
		var maxSeats = scheduleGR.capacity;
		var instructor = scheduleGR.instructor.toString();

		//7. verifica se já existe matrícula do usuário nesta agenda
		var enrollmentGR = new GlideRecord('x_1131775_traini_0_enrollment');
		enrollmentGR.addQuery('opened_by', user);
		enrollmentGR.addQuery('training_schedule', scheduleId);
		enrollmentGR.query();

		if (enrollmentGR.hasNext()) {
			return 'already_enrolled';
		}

		//8. Verifica se o usuário já fez 3 matrículas no mesmo curso
		var courseEnrollGR = new GlideRecord('x_1131775_traini_0_enrollment');
		courseEnrollGR.addQuery('opened_by', user);
		courseEnrollGR.addQuery('training_schedule.course', courseID);
		courseEnrollGR.query();

		var count = 0;
		while(courseEnrollGR.next()) {
			count++;
		}

		if (count >= 3) {
			return 'limit_reached';
		}

		//9. Verifica lotação máxima
		var seatsGR = new GlideRecord('x_1131775_traini_0_enrollment');
		seatsGR.addQuery('training_schedule', scheduleId);
		seatsGR.addQuery('state', 'IN', '2,3');
		seatsGR.query();

		var enrolledCount = 0;
		while (seatsGR.next()) {
			enrolledCount++;
		}

		if (enrolledCount >= maxSeats) {
			return 'no_seats_available';
		}

		//10. Instrutor não pode se matricular no próprio curso
		if (instructor === user) {
			return 'instructor_cannot_enroll';
		}

		//11. Só pode se matricular até 1 dia antes do curso
		var today = new GlideDateTime();
		var training = new GlideDateTime(trainingDate);
		var diff = GlideDate.subtract(today, training);
		//metodo subtract retorna objeto do tipo data, por isso tem que pegar o valor numerico
		var daysDiff = parseInt(diff.getNumericValue() / (1000 * 60 * 60 * 24));

		if (daysDiff < 1) {
			return 'too_late';
		}

		return 'ok';
	},

    type: 'EnrollmentValidation'
});
